REPLACEMENTS = {'tests/test_phase132_6_group_proof_narrative_renderer.py': {'test_phase132_6_sigma_family_statements_use_readable_labels': 'def test_phase132_6_sigma_family_statements_use_readable_labels():\n  data = build_phase132_6_sigma9_narrative(\n    max_depth=1,\n  )\n\n  presentation = data[\n    "presentation"\n  ]\n  rendered = data[\n    "rendered"\n  ]\n\n  root_edges = tuple(\n    edge\n    for edge in presentation.edges\n    if edge.parent_step is presentation.root_step\n  )\n\n  target_type_names = {\n    "Toda48Pi16_9OrderAndE4InjectiveStatement",\n    "TodaLemma514Sigma8Statement",\n    "TodaSigmaFamilyDefinitionStatement",\n  }\n\n  labelled_steps = tuple(\n    edge.premise_step\n    for edge in root_edges\n    if (\n      type(\n        edge.premise_step.conclusion\n      ).__name__\n      in target_type_names\n    )\n  )\n\n  assert {\n    type(\n      step.conclusion\n    ).__name__\n    for step in labelled_steps\n  } == target_type_names\n\n  assert r"\\pi_{16}^{9}" in rendered\n  assert r"\\mathbb{Z}/16" in rendered\n\n  for step in labelled_steps:\n    type_name = type(\n      step.conclusion\n    ).__name__\n\n    assert type_name not in rendered\n\n    if step.inference_rule is not None:\n      assert (\n        step.inference_rule.name\n        not in rendered\n      )\n'}, 'tests/test_phase132_8_group_proof_narrative_dedup.py': {'test_phase132_8_shared_dependency_subtree_is_expanded_once': 'def test_phase132_8_shared_dependency_subtree_is_expanded_once():\n  data = build_phase132_8_sigma9_narrative(\n    max_depth=2,\n  )\n\n  presentation = data[\n    "presentation"\n  ]\n  rendered = data[\n    "rendered"\n  ]\n\n  counts = _incoming_use_count_by_step_id(\n    presentation\n  )\n\n  shared_parent = next(\n    node.proof_step\n    for node in presentation.nodes\n    if (\n      counts[\n        id(\n          node.proof_step\n        )\n      ]\n      > 1\n      and any(\n        edge.parent_step\n        is node.proof_step\n        for edge in presentation.edges\n      )\n      and node.proof_step\n      is not presentation.root_step\n    )\n  )\n\n  parent_fact = _render_group_proof_narrative_fact(\n    shared_parent\n  )\n\n  assert parent_fact\n  assert rendered.count(\n    "Lemma 5.14.**"\n  ) == 1\n', 'test_phase132_8_repeated_shared_dependency_uses_existing_reference': 'def test_phase132_8_repeated_shared_dependency_uses_existing_reference():\n  data = build_phase132_8_sigma9_narrative(\n    max_depth=2,\n  )\n\n  presentation = data[\n    "presentation"\n  ]\n  rendered = data[\n    "rendered"\n  ]\n\n  counts = _incoming_use_count_by_step_id(\n    presentation\n  )\n\n  shared_steps = tuple(\n    node.proof_step\n    for node in presentation.nodes\n    if counts[\n      id(\n        node.proof_step\n      )\n    ] > 1\n  )\n\n  assert shared_steps\n  assert "[R1]" in rendered\n  assert rendered.count(\n    "Lemma 5.14.**"\n  ) == 1\n', 'test_phase132_8_root_conclusion_and_source_remain_unchanged': 'def test_phase132_8_root_conclusion_and_source_remain_unchanged():\n  data = build_phase132_8_sigma9_narrative(\n    max_depth=2,\n  )\n\n  rendered = data[\n    "rendered"\n  ]\n\n  assert "Lemma 5.14" in rendered\n  assert r"\\pi_{16}^{9}" in rendered\n  assert r"\\mathbb{Z}/16" in rendered\n', 'test_phase132_8_cli_narrative_uses_deduplicated_renderer': 'def test_phase132_8_cli_narrative_uses_deduplicated_renderer(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert r"\\pi_{16}^{9}" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n  assert captured.out.count(\n    "Lemma 5.14.**"\n  ) == 1\n'}, 'tests/test_phase133_10_sigma_label_wording.py': {'test_phase133_10_sigma9_depth_two_uses_final_japanese_wording': 'def test_phase133_10_sigma9_depth_two_uses_final_japanese_wording(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "Lemma 5.14" in captured.out\n  assert r"\\pi_{16}^{9}" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n\n  assert (\n    "Theorem 3.6 から Lemma 5.14 への σ″ bridge"\n    not in captured.out\n  )\n  assert (\n    "Toda Lemma 5.14 の σ′ branch"\n    not in captured.out\n  )\n'}, 'tests/test_phase133_6_group_proof_narrative_labels.py': {'test_phase133_6_pi10_4_uses_readable_nu4_decomposition_label': 'def test_phase133_6_pi10_4_uses_readable_nu4_decomposition_label(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "4",\n      "6",\n      "--depth",\n      "1",\n      "--mode",\n      "narrative",\n    ]\n  )\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert r"\\pi_{10}^{4}" in captured.out\n  assert r"\\mathbb{Z}/8" in captured.out\n  assert (\n    "Toda Proposition 5.6 finite-dimensional integration"\n    not in captured.out\n  )\n  assert (\n    "Toda (5.6) nu_4 decomposition isomorphism semantics"\n    not in captured.out\n  )\n', 'test_phase133_6_pi12_5_uses_readable_sigma_triple_prime_labels': 'def test_phase133_6_pi12_5_uses_readable_sigma_triple_prime_labels(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "5",\n      "7",\n      "--depth",\n      "1",\n      "--mode",\n      "narrative",\n    ]\n  )\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert r"\\pi_{12}^{5}" in captured.out\n  assert r"\\mathbb{Z}/2" in captured.out\n  assert (\n    "Toda Lemma 5.13 sigma triple-prime definition"\n    not in captured.out\n  )\n', 'test_phase133_6_sigma9_depth_two_reuses_new_labels': 'def test_phase133_6_sigma9_depth_two_reuses_new_labels(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert r"\\pi_{12}^{5}" in captured.out\n  assert r"\\mathbb{Z}/2" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n  assert "Lemma 5.14" in captured.out\n'}, 'tests/test_phase133_9_group_proof_narrative_labels.py': {'test_phase133_9_pi10_4_depth_two_uses_final_readable_labels': 'def test_phase133_9_pi10_4_depth_two_uses_final_readable_labels(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "4",\n      "6",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert r"\\pi_{10}^{4}" in captured.out\n  assert r"\\mathbb{Z}/8" in captured.out\n\n  internal_names = (\n    "Toda Proposition 5.6 finite-dimensional integration",\n    "Toda (5.6) nu_4 decomposition isomorphism semantics",\n    "Toda Lemma 5.4 integration",\n  )\n\n  for internal_name in internal_names:\n    assert internal_name not in captured.out\n', 'test_phase133_9_pi16_9_depth_two_uses_final_sigma_labels': 'def test_phase133_9_pi16_9_depth_two_uses_final_sigma_labels(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "9",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert "Lemma 5.14" in captured.out\n  assert r"\\mathbb{Z}/16" in captured.out\n\n  internal_names = (\n    "Toda Theorem 3.6 Lemma 5.14 sigma double-prime bridge",\n    "Toda Lemma 5.14 sigma-prime branch",\n  )\n\n  for internal_name in internal_names:\n    assert internal_name not in captured.out\n', 'test_phase133_9_previous_labels_remain_available': 'def test_phase133_9_previous_labels_remain_available(\n  capsys,\n):\n  exit_code = cli_main.main(\n    [\n      "group-proof",\n      "5",\n      "7",\n      "--depth",\n      "2",\n      "--mode",\n      "narrative",\n    ]\n  )\n\n  captured = capsys.readouterr()\n\n  assert exit_code == 0\n  assert captured.err == ""\n  assert r"\\pi_{12}^{5}" in captured.out\n  assert r"\\mathbb{Z}/2" in captured.out\n  assert "Lemma 5.13" in captured.out\n'}, 'tests/test_phase143_44_single_argument_narrative_renderer.py': {'test_phase143_44_pi6_3_order_combines_header_method_and_body': 'def test_phase143_44_pi6_3_order_combines_header_method_and_body():\n  (\n    _argument,\n    primary_component,\n    rendered,\n  ) = _single_argument_data(\n    3,\n    3,\n    TodaGroupProofNarrativeArgumentRole\n    .ESTABLISH_ORDER,\n    TodaGroupProofNarrativeArgumentDiscourseRole\n    .MIDDLE,\n  )\n\n  assert primary_component is not None\n  assert (\n    r"\\pi_{7}^{3} \\xrightarrow{H} "\n    r"\\pi_{7}^{5} \\xrightarrow{\\Delta} "\n    r"\\pi_{5}^{2} \\xrightarrow{E} "\n    r"\\pi_{6}^{3}"\n    in rendered\n  )\n  assert (\n    r"\\operatorname{ord}\\left(\\nu\'\\right) = 4"\n    in rendered\n  )\n', 'test_phase143_44_pi6_3_definition_without_primary_has_no_method_transition': 'def test_phase143_44_pi6_3_definition_without_primary_has_no_method_transition():\n  (\n    _argument,\n    primary_component,\n    rendered,\n  ) = _single_argument_data(\n    3,\n    3,\n    TodaGroupProofNarrativeArgumentRole\n    .ESTABLISH_DEFINITION,\n    TodaGroupProofNarrativeArgumentDiscourseRole\n    .FIRST,\n  )\n\n  assert primary_component is None\n  assert r"$\\nu\'$" in rendered\n  assert r"\\nu\' \\in " in rendered\n  assert "次の完全列を考える" not in rendered\n', 'test_phase143_44_pi8_5_detached_order_has_no_discourse_marker': 'def test_phase143_44_pi8_5_detached_order_has_no_discourse_marker():\n  (\n    _argument,\n    primary_component,\n    rendered,\n  ) = _single_argument_data(\n    5,\n    3,\n    TodaGroupProofNarrativeArgumentRole\n    .ESTABLISH_ORDER,\n    TodaGroupProofNarrativeArgumentDiscourseRole\n    .DETACHED,\n    occurrence=1,\n  )\n\n  assert primary_component is not None\n  assert r"$\\nu\'$" in rendered\n  assert not rendered.startswith(\n    "まず"\n  )\n  assert not rendered.startswith(\n    "次に"\n  )\n  assert not rendered.startswith(\n    "最後に"\n  )\n'}, 'tests/test_phase143_46_multi_argument_narrative_assembler.py': {'test_phase143_46_pi6_3_assembles_three_main_arguments': 'def test_phase143_46_pi6_3_assembles_three_main_arguments():\n  rendered = _render_multi_argument(\n    3,\n    3,\n  )\n\n  assert r"$\\nu\'$" in rendered\n  assert (\n    r"\\operatorname{ord}\\left(\\nu\'\\right) = 4"\n    in rendered\n  )\n  assert r"\\pi_{6}^{3}" in rendered\n  assert r"\\mathbb{Z}/4" in rendered\n', 'test_phase143_46_pi16_9_assembles_definition_then_group_structure': 'def test_phase143_46_pi16_9_assembles_definition_then_group_structure():\n  rendered = _render_multi_argument(\n    9,\n    7,\n  )\n\n  assert r"\\sigma_{9}" in rendered\n  assert r"\\pi_{16}^{9}" in rendered\n  assert r"\\mathbb{Z}/16" in rendered\n'}, 'tests/test_phase143_61b_direct_premise_narrative.py': {'test_phase143_61b_pi8_5_places_direct_derivation_premises_together': 'def test_phase143_61b_pi8_5_places_direct_derivation_premises_together():\n  rendered = _render(\n    5,\n    3,\n  )\n\n  double_relation = (\n    r"$2\\nu_{5} = E^{2}\\nu\'$"\n  )\n  e2_order = (\n    r"$\\operatorname{ord}\\left(E^{2}\\nu\'\\right) = 4$"\n  )\n  conclusion = (\n    r"$\\operatorname{ord}\\left(\\nu_{5}\\right) = 8$"\n  )\n\n  assert rendered.count(\n    double_relation\n  ) == 1\n  assert rendered.count(\n    e2_order\n  ) == 1\n  assert (\n    rendered.index(\n      double_relation\n    )\n    < rendered.index(\n      e2_order\n    )\n    < rendered.index(\n      conclusion\n    )\n  )\n', 'test_phase143_61b_pi6_3_keeps_local_calculation_derivation': 'def test_phase143_61b_pi6_3_keeps_local_calculation_derivation():\n  rendered = _render(\n    3,\n    3,\n  )\n\n  source_one = (\n    r"$2\\nu\' = \\eta_{3}E\\eta_{3}\\eta_{5}\\tag{1}$"\n  )\n  source_two = (\n    r"$\\eta_{3}E\\eta_{3}\\eta_{5} = \\eta_{3}^{3}\\tag{2}$"\n  )\n  target = (\n    r"$2\\nu\' = \\eta_{3}^{3}\\tag{3}$"\n  )\n\n  assert (\n    rendered.index(\n      source_one\n    )\n    < rendered.index(\n      source_two\n    )\n    < rendered.index(\n      target\n    )\n  )\n'}, 'tests/test_phase143_74b_remaining_internal_narrative.py': {'test_phase143_74b_prop44_isomorphism_renders_decomposition_semantics': 'def test_phase143_74b_prop44_isomorphism_renders_decomposition_semantics():\n  beta = HomotopyElement(\n    name="beta",\n    dimension=6,\n  )\n  gamma = HomotopyElement(\n    name="gamma",\n    dimension=6,\n  )\n  formula = Sum(\n    left=Suspension(\n      expression=beta,\n    ),\n    right=gamma,\n  )\n  decomposition_map = TodaProp44DecompositionMap(\n    source_group=DirectSumGroup(\n      summands=(),\n    ),\n    target_group=TodaPrimaryGroup(7, 4),\n    alpha=beta,\n    beta=beta,\n    gamma=gamma,\n    formula=formula,\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    _step(\n      TodaProp44IsomorphismStatement(\n        map=decomposition_map,\n      )\n    )\n  )\n\n  assert "TodaProp44IsomorphismStatement" not in rendered\n  assert r"\\mapsto" in rendered\n  assert "同型写像" in rendered\n', 'test_phase143_74b_suspension_isomorphism_renders_semantic_map': 'def test_phase143_74b_suspension_isomorphism_renders_semantic_map():\n  rendered = _render_group_proof_narrative_fact(\n    _step(\n      TodaSuspensionIsomorphismStatement(\n        map=TodaSuspensionMap(\n          source_group=TodaPrimaryGroup(6, 4),\n          target_group=TodaPrimaryGroup(7, 5),\n        )\n      )\n    )\n  )\n\n  assert r"$E: \\pi_{6}^{4}" in rendered\n  assert r"\\pi_{7}^{5}$" in rendered\n  assert "同型写像" in rendered\n  assert "TodaSuspensionIsomorphismStatement" not in rendered\n'}, 'tests/test_phase143_75c_generic_semantic_rendering.py': {'test_phase143_75c_renders_toda45_isomorphism_semantically': 'def test_phase143_75c_renders_toda45_isomorphism_semantically():\n  proof_step = _find_production_step(\n    n=4,\n    k=1,\n    statement_type=Toda45IsomorphismStatement,\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert rendered.startswith(\n    "$E^{"\n  )\n  assert r"\\to" in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n', 'test_phase143_75c_renders_hopf_isomorphism_semantically': 'def test_phase143_75c_renders_hopf_isomorphism_semantically():\n  proof_step = _find_production_step(\n    n=2,\n    k=1,\n    statement_type=(\n      TodaHopfInvariantIsomorphismStatement\n    ),\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert rendered.startswith(\n    "$H: "\n  )\n  assert r"\\to" in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n', 'test_phase143_75c_renders_prop44_second_summand_semantically': 'def test_phase143_75c_renders_prop44_second_summand_semantically():\n  proof_step = _find_production_step(\n    n=2,\n    k=2,\n    statement_type=(\n      TodaProp44SecondSummandRestrictionStatement\n    ),\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert r"\\eta_{2}" in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n  assert (\n    type(\n      proof_step.conclusion\n    ).__name__\n    not in rendered\n  )\n'}, 'tests/test_phase143_75f_ehp_semantic_rendering.py': {'test_phase143_75f_renders_delta_surjective_semantically': 'def test_phase143_75f_renders_delta_surjective_semantically():\n  proof_step = _find_production_step(\n    n=3,\n    k=5,\n    statement_type=TodaDeltaSurjectiveStatement,\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert r"\\Delta:" in rendered\n  assert r"\\to" in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n', 'test_phase143_75f_renders_delta_kernel_semantically': 'def test_phase143_75f_renders_delta_kernel_semantically():\n  proof_step = _find_production_step(\n    n=6,\n    k=5,\n    statement_type=(\n      TodaDeltaKernelFreeCyclicStatement\n    ),\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert r"\\ker\\Delta" in rendered\n  assert r"\\mathbb{Z}\\{" in rendered\n  assert r"\\iota_{11}" in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n'}, 'tests/test_phase143_75i_whitehead_hopf_semantic_rendering.py': {'test_phase143_75i_renders_prop27_whitehead_argument_semantically': 'def test_phase143_75i_renders_prop27_whitehead_argument_semantically():\n  proof_step = _find_production_step(\n    n=3,\n    k=1,\n    statement_type=(\n      TodaProp27HopfInvariantUpToSignStatement\n    ),\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert (\n    r"$H([\\iota_{2}, \\iota_{2}])"\n    r" = \\pm 2\\iota_{3}$"\n    in rendered\n  )\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n', 'test_phase143_75i_renders_prop27_map_application_semantically': 'def test_phase143_75i_renders_prop27_map_application_semantically():\n  proof_step = _find_production_step(\n    n=6,\n    k=5,\n    statement_type=(\n      TodaProp27HopfInvariantUpToSignStatement\n    ),\n    predicate=lambda statement: (\n      type(\n        statement.argument\n      ).__name__\n      == "MapApplication"\n    ),\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert rendered.startswith(\n    r"$H(\\Delta\\left("\n  )\n  assert r" = \\pm " in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n', 'test_phase143_75i_renders_58_whitehead_square_semantically': 'def test_phase143_75i_renders_58_whitehead_square_semantically():\n  proof_step = _find_production_step(\n    n=5,\n    k=4,\n    statement_type=(\n      Toda58WhiteheadSquareUpToSignStatement\n    ),\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    proof_step\n  )\n\n  assert (\n    r"$[\\iota_{4}, \\iota_{4}]"\n    in rendered\n  )\n  assert r" = \\pm " in rendered\n  assert r"2\\nu_{4}" in rendered\n  assert r"E\\nu\'" in rendered\n  assert (\n    proof_step.inference_rule.name\n    not in rendered\n  )\n'}, 'tests/test_phase143_75p_prop44_suspension_injective_semantic_rendering.py': {'test_phase143_75p_all_target_occurrences_render_semantically': 'def test_phase143_75p_all_target_occurrences_render_semantically():\n  steps = _target_steps()\n\n  assert len(\n    steps\n  ) >= 55\n\n  for step in steps:\n    rendered = _render_group_proof_narrative_fact(\n      step\n    )\n    assert rendered.startswith(\n      "$E: "\n    )\n    assert r" \\to " in rendered\n    assert rendered != step.inference_rule.name\n', 'test_phase143_75p_both_rule_families_use_same_semantic_renderer': 'def test_phase143_75p_both_rule_families_use_same_semantic_renderer():\n  steps = _target_steps()\n\n  rule_counts = Counter(\n    step.inference_rule.name\n    for step in steps\n  )\n\n  assert (\n    "Toda Proposition 5.3 n=4 "\n    "Phase 48 injectivity bridge"\n    in rule_counts\n  )\n  assert (\n    "Toda Proposition 4.4 "\n    "suspension injectivity"\n    in rule_counts\n  )\n  assert all(\n    count > 0\n    for count in rule_counts.values()\n  )\n\n  for step in steps:\n    rendered = _render_group_proof_narrative_fact(\n      step\n    )\n    assert "Proposition" not in rendered\n    assert "injectivity" not in rendered\n', 'test_phase143_75p_concrete_map_uses_source_and_target_groups': 'def test_phase143_75p_concrete_map_uses_source_and_target_groups():\n  steps = _target_steps()\n\n  concrete = next(\n    step\n    for step in steps\n    if (\n      repr(step.conclusion.map.source_group)\n      == (\n        "TodaPrimaryGroup("\n        "group_dimension=5, "\n        "sphere_dimension=3)"\n      )\n      and repr(step.conclusion.map.target_group)\n      == (\n        "TodaPrimaryGroup("\n        "group_dimension=6, "\n        "sphere_dimension=4)"\n      )\n    )\n  )\n\n  rendered = _render_group_proof_narrative_fact(\n    concrete\n  )\n\n  assert r"$E: \\pi_{5}^{3}" in rendered\n  assert r"\\pi_{6}^{4}$" in rendered\n  assert concrete.inference_rule.name not in rendered\n'}, 'tests/test_phase143_75s_toda58_whitehead_square_semantic_rendering.py': {'test_phase143_75s_all_aggregate_components_render_semantically': 'def test_phase143_75s_all_aggregate_components_render_semantically():\n  statements = _target_statements()\n\n  assert len(\n    statements\n  ) >= 45\n\n  rendered = tuple(\n    render_toda_proof_statement_latex(\n      statement\n    )\n    for statement in statements\n  )\n\n  assert all(\n    value is not None\n    for value in rendered\n  )\n\n  assert all(\n    type(\n      statement\n    ).__name__\n    == "Toda58WhiteheadSquareUpToSignStatement"\n    for statement in statements\n  )\n'}, 'tests/test_phase150_rc4_5b_3_r1_beta_latex.py': {'test_phase150_rc4_5b_3_r1_beta_uses_general_greek_latex_table': 'def test_phase150_rc4_5b_3_r1_beta_uses_general_greek_latex_table():\n  beta = HomotopyElement(\n    name="β",\n    dimension=3,\n    source=6,\n    target=3,\n  )\n\n  assert render_toda_expression_latex(\n    beta\n  ) == r"\\beta"\n'}, 'tests/test_phase150_rc4_7a_cross_group_reference_normalization.py': {'test_phase150_rc4_7a_pi10_4_numbers_normalized_references': 'def test_phase150_rc4_7a_pi10_4_numbers_normalized_references(\n):\n  rendered = _render_group(\n    4,\n    6,\n  )\n\n  assert "使用する結果を先にまとめる." in rendered\n  assert "[R1]" in rendered\n  assert r"\\pi_{10}^{4}" in rendered\n  assert r"\\mathbb{Z}/8" in rendered\n', 'test_phase150_rc4_7a_pi12_5_numbers_normalized_references': 'def test_phase150_rc4_7a_pi12_5_numbers_normalized_references(\n):\n  rendered = _render_group(\n    5,\n    7,\n  )\n\n  assert "使用する結果を先にまとめる." in rendered\n  assert "[R1]" in rendered\n  assert r"\\pi_{12}^{5}" in rendered\n  assert r"\\mathbb{Z}/2" in rendered\n'}, 'tests/test_phase150_rc4_7d_3_public_narrative_generic_route.py': {'test_phase150_rc4_7d_3_pi10_public_and_web_use_generic_reason_route': 'def test_phase150_rc4_7d_3_pi10_public_and_web_use_generic_reason_route():\n  markdown = render_toda_group_proof_narrative_markdown(\n    _presentation(\n      4,\n      6,\n    )\n  )\n  web_text = _web_text(\n    4,\n    6,\n  )\n\n  assert "以上で得た群構造" in markdown\n  assert "結果を合わせると" in markdown\n  assert "以上で得た群構造" in web_text\n  assert "結果を合わせると" in web_text\n', 'test_phase150_rc4_7d_3_pi12_public_and_web_use_generic_reason_route': 'def test_phase150_rc4_7d_3_pi12_public_and_web_use_generic_reason_route():\n  markdown = render_toda_group_proof_narrative_markdown(\n    _presentation(\n      5,\n      7,\n    )\n  )\n  web_text = _web_text(\n    5,\n    7,\n  )\n\n  assert "この完全性" in markdown\n  assert "結果を合わせると" in markdown\n  assert "この完全性" in web_text\n  assert "結果を合わせると" in web_text\n'}}
